const raw =
  $json.output?.[0]?.content?.[0]?.text
  ?? $json.text
  ?? '';

const cleaned = String(raw)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let data;

try {
  data = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `AI response is not valid JSON: ${error.message}`
  );
}

// Original topic + all reusable settings.
// This also preserves future fields such as Telegram chat_id.
const source = $('Set Content Preferences').first().json;

return [{
  json: {
    ...source,

    instagram: String(data.instagram ?? '').trim(),
    tiktok: String(data.tiktok ?? '').trim(),
    youtube_title: String(data.youtube_title ?? '').trim(),
    youtube_description: String(data.youtube_description ?? '').trim(),
    threads: String(data.threads ?? '').trim(),

    ai_parse_status: 'passed'
  }
}];

const items = $input.all();

function countHashtags(text) {
  return (String(text).match(/#[\p{L}\p{N}_]+/gu) ?? []).length;
}

function containsEmoji(text) {
  return /\p{Extended_Pictographic}/u.test(String(text));
}

function normalize(text) {
  return String(text)
    .toLowerCase()
    .replace(/#[\p{L}\p{N}_]+/gu, '')
    .replace(/[^\p{L}\p{N}\s]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
}

return items.map(item => {
  const data = item.json;

  const includeHashtags =
    data.include_hashtags === true ||
    String(data.include_hashtags).toLowerCase() === 'true';

  const includeEmojis =
    data.include_emojis === true ||
    String(data.include_emojis).toLowerCase() === 'true';

  const requiredFields = [
    'instagram',
    'tiktok',
    'youtube_title',
    'youtube_description',
    'threads'
  ];

  for (const field of requiredFields) {
    if (!data[field] || !String(data[field]).trim()) {
      throw new Error(`Missing generated field: ${field}`);
    }
  }

  const instagram = String(data.instagram).trim();
  const tiktok = String(data.tiktok).trim();
  const youtubeTitle = String(data.youtube_title).trim();
  const youtubeDescription = String(data.youtube_description).trim();
  const threads = String(data.threads).trim();

  // Character limits
  if (instagram.length > 600) {
    throw new Error(
      `Instagram caption is too long: ${instagram.length}/600 characters.`
    );
  }

  if (tiktok.length > 180) {
    throw new Error(
      `TikTok caption is too long: ${tiktok.length}/180 characters.`
    );
  }

  if (youtubeTitle.length > 70) {
    throw new Error(
      `YouTube Shorts title is too long: ${youtubeTitle.length}/70 characters.`
    );
  }

  if (youtubeDescription.length > 250) {
    throw new Error(
      `YouTube Shorts description is too long: ${youtubeDescription.length}/250 characters.`
    );
  }

  if (threads.length > 300) {
    throw new Error(
      `Threads post is too long: ${threads.length}/300 characters.`
    );
  }

  // Hashtags
  const hashtagCounts = {
    instagram: countHashtags(instagram),
    tiktok: countHashtags(tiktok),
    youtube_description: countHashtags(youtubeDescription),
    threads: countHashtags(threads)
  };

  if (includeHashtags) {
    if (hashtagCounts.instagram !== 5) {
      throw new Error(
        `Instagram must contain exactly 5 hashtags. Received ${hashtagCounts.instagram}.`
      );
    }

    if (hashtagCounts.tiktok !== 4) {
      throw new Error(
        `TikTok must contain exactly 4 hashtags. Received ${hashtagCounts.tiktok}.`
      );
    }

    if (hashtagCounts.youtube_description !== 3) {
      throw new Error(
        `YouTube description must contain exactly 3 hashtags. Received ${hashtagCounts.youtube_description}.`
      );
    }

    if (hashtagCounts.threads > 2) {
      throw new Error(
        `Threads may contain a maximum of 2 hashtags. Received ${hashtagCounts.threads}.`
      );
    }
  } else {
    const totalHashtags =
      hashtagCounts.instagram +
      hashtagCounts.tiktok +
      hashtagCounts.youtube_description +
      hashtagCounts.threads;

    if (totalHashtags > 0) {
      throw new Error(
        'Hashtags were generated even though include_hashtags is disabled.'
      );
    }
  }

  // Emoji validation
  if (!includeEmojis) {
    const contentWithEmoji = [];

    if (containsEmoji(instagram)) contentWithEmoji.push('Instagram');
    if (containsEmoji(tiktok)) contentWithEmoji.push('TikTok');
    if (containsEmoji(youtubeTitle)) contentWithEmoji.push('YouTube title');
    if (containsEmoji(youtubeDescription)) {
      contentWithEmoji.push('YouTube description');
    }
    if (containsEmoji(threads)) contentWithEmoji.push('Threads');

    if (contentWithEmoji.length > 0) {
      throw new Error(
        `Emojis were generated even though include_emojis is disabled: ${contentWithEmoji.join(', ')}.`
      );
    }
  }

  // Cross-platform duplication check
  const bodies = {
    instagram: normalize(instagram),
    tiktok: normalize(tiktok),
    youtube_description: normalize(youtubeDescription),
    threads: normalize(threads)
  };

  const entries = Object.entries(bodies);

  for (let i = 0; i < entries.length; i++) {
    for (let j = i + 1; j < entries.length; j++) {
      const [nameA, textA] = entries[i];
      const [nameB, textB] = entries[j];

      if (textA && textB && textA === textB) {
        throw new Error(
          `${nameA} and ${nameB} content are identical and should be platform-specific.`
        );
      }
    }
  }

  return {
    json: {
      ...data,

      validation_status: 'passed',

      character_counts: {
        instagram: instagram.length,
        tiktok: tiktok.length,
        youtube_title: youtubeTitle.length,
        youtube_description: youtubeDescription.length,
        threads: threads.length
      },

      hashtag_counts: hashtagCounts
    }
  };
});

const data = $input.first().json;
const settings = $('Set Content Preferences').first().json;

// Topic can come either from Manual Input or Telegram Input
const topic =
  data.topic ??
  settings.topic ??
  '';

return [{
  json: {
    // Needed to send the result back to the same Telegram user
    chat_id: data.chat_id ?? null,

    status: 'ready_for_review',

    source: {
      topic
    },

    content_settings: {
      tone: settings.tone,
      target_audience: settings.target_audience,
      language: settings.language,
      brand_voice: settings.brand_voice,
      call_to_action: settings.call_to_action,
      include_emojis: settings.include_emojis,
      include_hashtags: settings.include_hashtags
    },

    platforms: {
      instagram: {
        caption: data.instagram,
        characters: data.character_counts.instagram,
        hashtags: data.hashtag_counts.instagram,
        max_characters: 600
      },

      tiktok: {
        caption: data.tiktok,
        characters: data.character_counts.tiktok,
        hashtags: data.hashtag_counts.tiktok,
        max_characters: 180
      },

      youtube_shorts: {
        title: data.youtube_title,
        description: data.youtube_description,
        title_characters: data.character_counts.youtube_title,
        description_characters: data.character_counts.youtube_description,
        hashtags: data.hashtag_counts.youtube_description,
        title_max_characters: 70,
        description_max_characters: 250
      },

      threads: {
        post: data.threads,
        characters: data.character_counts.threads,
        hashtags: data.hashtag_counts.threads,
        max_characters: 300
      }
    },

    quality_control: {
      quality_score: data.quality_score ?? 100,
      quality_status: data.quality_status ?? 'passed',
      quality_issues: data.quality_issues ?? [],
      quality_issue_count: data.quality_issue_count ?? 0,
      validation_status: data.validation_status,
      all_platforms_validated: true
    }
  }
}];

const data = $input.first().json;

const instagram = String(
  data.instagram ?? data.instagram_caption ?? ''
).trim();

const tiktok = String(
  data.tiktok ?? data.tiktok_caption ?? ''
).trim();

const youtubeTitle = String(
  data.youtube_title ?? ''
).trim();

const youtubeDescription = String(
  data.youtube_description ?? ''
).trim();

const threads = String(
  data.threads ?? data.threads_post ?? ''
).trim();

const includeHashtags =
  data.include_hashtags === true ||
  String(data.include_hashtags).toLowerCase() === 'true';

const includeEmojis =
  data.include_emojis === true ||
  String(data.include_emojis).toLowerCase() === 'true';

let score = 100;
const issues = [];

function addIssue(message, penalty = 10) {
  issues.push(message);
  score -= penalty;
}

function countHashtags(text) {
  return (String(text).match(/#[\p{L}\p{N}_]+/gu) ?? []).length;
}

function containsEmoji(text) {
  return /\p{Extended_Pictographic}/u.test(String(text));
}

function normalize(text) {
  return String(text)
    .toLowerCase()
    .replace(/#[\p{L}\p{N}_]+/gu, '')
    .replace(/[^\p{L}\p{N}\s]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// Required fields
if (!instagram) addIssue('Instagram caption is missing.', 25);
if (!tiktok) addIssue('TikTok caption is missing.', 25);
if (!youtubeTitle) addIssue('YouTube title is missing.', 25);
if (!youtubeDescription) addIssue('YouTube description is missing.', 25);
if (!threads) addIssue('Threads post is missing.', 25);

// Character limits
if (instagram.length > 600) {
  addIssue(`Instagram caption exceeds 600 characters (${instagram.length}).`);
}

if (tiktok.length > 180) {
  addIssue(`TikTok caption exceeds 180 characters (${tiktok.length}).`);
}

if (youtubeTitle.length > 70) {
  addIssue(`YouTube title exceeds 70 characters (${youtubeTitle.length}).`);
}

if (youtubeDescription.length > 250) {
  addIssue(
    `YouTube description exceeds 250 characters (${youtubeDescription.length}).`
  );
}

if (threads.length > 300) {
  addIssue(`Threads post exceeds 300 characters (${threads.length}).`);
}

// Hashtag validation
const hashtagCounts = {
  instagram: countHashtags(instagram),
  tiktok: countHashtags(tiktok),
  youtube_description: countHashtags(youtubeDescription),
  threads: countHashtags(threads)
};

if (includeHashtags) {
  if (hashtagCounts.instagram !== 5) {
    addIssue(
      `Instagram must contain exactly 5 hashtags; found ${hashtagCounts.instagram}.`
    );
  }

  if (hashtagCounts.tiktok !== 4) {
    addIssue(
      `TikTok must contain exactly 4 hashtags; found ${hashtagCounts.tiktok}.`
    );
  }

  if (hashtagCounts.youtube_description !== 3) {
    addIssue(
      `YouTube description must contain exactly 3 hashtags; found ${hashtagCounts.youtube_description}.`
    );
  }

  if (hashtagCounts.threads > 2) {
    addIssue(
      `Threads must contain no more than 2 hashtags; found ${hashtagCounts.threads}.`
    );
  }
} else {
  const totalHashtags =
    hashtagCounts.instagram +
    hashtagCounts.tiktok +
    hashtagCounts.youtube_description +
    hashtagCounts.threads;

  if (totalHashtags > 0) {
    addIssue(
      'Hashtags were generated even though include_hashtags is disabled.'
    );
  }
}

// Emoji validation
if (!includeEmojis) {
  const contentWithEmoji = [];

  if (containsEmoji(instagram)) contentWithEmoji.push('Instagram');
  if (containsEmoji(tiktok)) contentWithEmoji.push('TikTok');
  if (containsEmoji(youtubeTitle)) contentWithEmoji.push('YouTube title');
  if (containsEmoji(youtubeDescription)) {
    contentWithEmoji.push('YouTube description');
  }
  if (containsEmoji(threads)) contentWithEmoji.push('Threads');

  if (contentWithEmoji.length > 0) {
    addIssue(
      `Emojis were generated even though include_emojis is disabled: ${contentWithEmoji.join(', ')}.`
    );
  }
}

// Detect identical cross-platform content
const bodies = {
  instagram: normalize(instagram),
  tiktok: normalize(tiktok),
  youtube_description: normalize(youtubeDescription),
  threads: normalize(threads)
};

const bodyEntries = Object.entries(bodies);

for (let i = 0; i < bodyEntries.length; i++) {
  for (let j = i + 1; j < bodyEntries.length; j++) {
    const [nameA, textA] = bodyEntries[i];
    const [nameB, textB] = bodyEntries[j];

    if (textA && textB && textA === textB) {
      addIssue(
        `${nameA} and ${nameB} content are identical and should be platform-specific.`,
        15
      );
    }
  }
}

score = Math.max(0, score);

const qualityStatus =
  issues.length === 0
    ? 'passed'
    : 'needs_regeneration';

return [{
  json: {
    ...data,

    quality_score: score,
    quality_status: qualityStatus,
    quality_issues: issues,
    quality_issue_count: issues.length,

    character_counts: {
      instagram: instagram.length,
      tiktok: tiktok.length,
      youtube_title: youtubeTitle.length,
      youtube_description: youtubeDescription.length,
      threads: threads.length
    },

    hashtag_counts: hashtagCounts
  }
}];

const data = $input.first().json;

// Failed result
if (data.status === 'failed_after_retries') {
  const issues = Array.isArray(data.quality_issues)
    ? data.quality_issues
        .map((issue, index) => `${index + 1}. ${issue}`)
        .join('\n')
    : 'No details available';

  const message = [
    '❌ CONTENT PACK NEEDS REVIEW',
    '',
    `Quality score: ${data.quality_score ?? 0}/100`,
    '',
    'Detected issues:',
    issues,
    '',
    'The content did not pass quality control after the maximum number of regeneration attempts.',
    '',
    'Change the topic or content settings and run the workflow again.'
  ].join('\n');

  return [{
    json: {
      ...data,
      telegram_message: message,
      telegram_result_type: 'failed'
    }
  }];
}


// Successful result
const instagram =
  data.platforms?.instagram?.caption ?? '';

const tiktok =
  data.platforms?.tiktok?.caption ?? '';

const youtubeTitle =
  data.platforms?.youtube_shorts?.title ?? '';

const youtubeDescription =
  data.platforms?.youtube_shorts?.description ?? '';

const threads =
  data.platforms?.threads?.post ?? '';

const topic =
  data.source?.topic ?? '';

const message = [
  '✅ CONTENT PACK READY',
  '',
  '📌 TOPIC',
  topic,
  '',
  '📸 INSTAGRAM',
  instagram,
  '',
  '🎵 TIKTOK',
  tiktok,
  '',
  '▶️ YOUTUBE SHORTS',
  '',
  'Title:',
  youtubeTitle,
  '',
  'Description:',
  youtubeDescription,
  '',
  '🧵 THREADS',
  threads,
  '',
  '✅ Quality control passed'
].join('\n');

return [{
  json: {
    ...data,
    telegram_message: message,
    telegram_result_type: 'success'
  }
}];
